function record(target,before,after,reason,endpoint,undo){let id=++ledgerSequence;state.ledger.unshift({id,target,before,after,reason,endpoint,time:new Date().toLocaleTimeString(),actor:'Preview operator (RK)'});renderLedger();window.dispatchEvent(new CustomEvent('system-change',{detail:{target}}));toast('Local preview applied · '+target+' · no request sent.',undo?()=>{undo();state.ledger.unshift({id:++ledgerSequence,target:'Undid local preview: '+target,before:after,after:before,reason:'Reversed in-memory edit within 10 seconds',endpoint:'Local only',time:new Date().toLocaleTimeString(),actor:'Preview operator (RK)'});renderAllData();renderLedger();}:null);}
function renderLedger(){let first=state.ledger[0];$$('[data-ledger]').forEach(el=>{el.innerHTML=first?'<p><strong>'+E(first.target)+'</strong></p><p>'+E(first.actor)+' · <time>'+E(first.time)+'</time> · local session</p>':'<p>No local changes in this session.</p><p class="subtle">Reviewed previews appear here. No server audit has been read or written.</p>';});$$('[data-ledger-count]').forEach(el=>el.textContent=state.ledger.length);}
function ledgerDialog(){let html='<p class="note">Local preview ledger · this session only. Not a server audit trail. Reasons are internal prototype notes.</p>';html+=state.ledger.length?'<ol class="ledger-items">'+state.ledger.map(a=>'<li class="ledger-item"><strong>'+E(a.target)+'</strong><small>'+E(a.actor)+' · '+E(a.time)+' · local time</small><p>'+E(a.reason)+'</p><details><summary>Review difference & contract</summary><pre class="diff-box" tabindex="0">'+E('Before: '+a.before+'\nAfter: '+a.after+'\nContract reference: '+a.endpoint)+'</pre></details></li>').join('')+'</ol>':'<div class="empty-state"><h3>No local changes yet</h3><p>Open a setting, flag or template, review a change and confirm it to see its local receipt here.</p></div>';info('Local change ledger',html);}
function review(o,commit){let d=$('#review-dialog');if(d.open)return;confirmOptions=o;confirmAction=commit;$('#review-title').textContent=o.title;$('#review-impact').textContent=o.impact;$('#review-diff').textContent=o.diff||'';$('#review-diff').hidden=!o.diff;$('#reason-wrap').hidden=o.reason===false;$('#review-reason').value='';$('#review-reason').removeAttribute('aria-invalid');$('#typed-wrap').hidden=!o.typed;$('#review-typed').value='';$('#review-typed').removeAttribute('aria-invalid');$('#review-errors').hidden=true;$('#review-submit').textContent=o.submit||'Confirm local change';$('#review-submit').disabled=false;d.showModal();$('#review-cancel').focus();}
function commitReview(){if(!confirmAction)return;let o=confirmOptions,reasons=[];if(o.reason!==false&&!$('#review-reason').value.trim()){reasons.push('Add a reason for the local ledger.');$('#review-reason').setAttribute('aria-invalid','true');}if(o.typed&&$('#review-typed').value!=='CLEAR'){reasons.push('Type CLEAR exactly to acknowledge the full cache flush.');$('#review-typed').setAttribute('aria-invalid','true');}if(reasons.length){$('#review-errors').textContent=reasons.join(' ');$('#review-errors').hidden=false;$('#review-errors').focus();return;}if(o.permission!==false&&state.permission!=='edit'){$('#review-dialog').close();permitted();return;}let fn=confirmAction,reason=$('#review-reason').value.trim();$('#review-submit').disabled=true;$('#review-submit').textContent='Applying local preview…';setTimeout(()=>{if(!$('#review-dialog').open)return;$('#review-dialog').close();fn(reason);},200);}
function chooseTab(name,focus=false){if(!['health','config','features','jobs','templates','operations'].includes(name))name=defaultTab;state.tab=name;$$('.main-tabs [data-tab]').forEach(b=>{let on=b.dataset.tab===name;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});$$('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==name);setView('ready');try{let u=new URL(location.href);u.searchParams.set('tab',name);history.replaceState(null,'',u.pathname+u.search+u.hash);}catch(e){}document.title='System · '+name[0].toUpperCase()+name.slice(1)+' · F24 V'+variant+' · Nestlancer';if(focus)$('.main-tabs [data-tab="'+name+'"]')?.focus();announce(name+' workspace selected. Captured data; local prototype.');window.dispatchEvent(new CustomEvent('system-tab',{detail:{name}}));}
function setView(view){state.view=view;let box=$('#simulation');if(!box)return;let ready=view==='ready';box.hidden=ready;$$('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==state.tab||!ready);$$('[data-state]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.state===view)));if(ready){box.innerHTML='';return;}if(view==='loading')box.innerHTML='<p class="eyebrow">Simulated loading · no request running</p><h2>Loading workspace</h2><p>Captured summary stays available while the work area loads.</p><div class="skeletons" aria-label="Loading placeholder"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><button class="btn" data-act="recover" style="margin-top:24px">Return to captured data</button>';else if(view==='empty')box.innerHTML='<div class="empty-state"><h2>No records in this preview</h2><p>This is a designed empty state, not a claim that the captured system has zero records. Restore the captured workspace to continue.</p><button class="btn primary" data-act="recover">Restore captured data</button></div>';else{box.innerHTML='<div class="note error" role="alert" tabindex="-1"><h2>Workspace could not load</h2><p style="color:inherit">Simulated error. No live outage was detected. The historical summary is retained; retry restores the local data.</p><button class="btn" data-act="recover">Retry local preview</button></div>';setTimeout(()=>$('[role=alert]',box)?.focus(),0);}announce('Prototype '+view+' state.');}
